vyatta_cfg_cmd_run () 
{ 
    local cmd=$1;
    local output='';
    if [[ "$cmd" == "edit" ]]; then
        vyatta_config_edit "${@:2}";
    else
        if [[ "$cmd" == "show" ]]; then
            vyatta_config_show "${@:2}";
        else
            if test -f "/var/run/vyconf_backend"; then
                cmd="${vyconf_bin_dir}/vy_$cmd";
            else
                cmd="/opt/vyatta/sbin/my_$cmd";
            fi;
            output=$($cmd "${@:2}");
        fi;
    fi;
    vyatta_cfg_print_output "$output"
}

